Translate("frFR", "onyxias-lair", {
	title = "Repaire d'Onyxia",
	aliases = { "Antre d'Onyxia" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Repaire d'Onyxia est une vaste caverne sous la {link:wyrmbog}Tourbière du Ver{/link}, à l'extrême sud du {link:dustwallow-marsh}Marécage d'Âprefange{/link}. Un large tunnel descend de la pierre calcinée de la tourbière vers les ténèbres, et à son extrémité s'ouvre une immense salle de roche noire, fendue de crevasses de feu. C'est l'antre d'{link:onyxia}Onyxia{/link}, fille d'{link:deathwing}Aile-de-mort{/link} et mère de la couvée du Vol noir. Ses œufs reposent dans les grottes qui bordent ses parois, et ses gardes veillent dans le tunnel. Rares sont ceux qui, n'étant pas de son vol, ont vu le repaire et en sont revenus.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit quand {link:onyxia}Onyxia{/link} établit son antre dans le marais, ni combien de temps la caverne fut sienne avant que les mortels ne l'apprennent. Ce que l'on sait, c'est que sa couvée remonta du sud et fondit sur les ogres du {red:stonemaul-ogres}clan Cognepierres{/red}. Les ogres perdirent leur village et s'enfuirent vers le nord, dans les roseaux. {link:draz-zilb}Draz'Zilb{/link}, l'érudit des Cognepierres, remonta la piste des dragonnets jusqu'à leur mère par les arts des arcanes. Il ne croyait pas qu'une fille d'{link:deathwing}Aile-de-mort{/link} fût venue si loin pour le seul plaisir d'assiéger une bande d'ogres. Pourquoi elle choisit ce marais, si près de {link:theramore-isle}Theramore{/link} et des terres de la {link:horde}Horde{/link}, nul ne l'a encore appris.]=],
		},
		{
			title = "Le temps présent",
			text = [=[{link:wyrmbog}La Tourbière du Ver{/link} est devenue un lieu de ponte. Les œufs d'{link:onyxia}Onyxia{/link} sont éparpillés dans le cloaque aux dragons, et ses dragonnets et ses drakes chassent dans le sud du marais. Dans une tanière voisine, l'ancien drake {link:emberstrife}Brandeguerre{/link} met à l'épreuve les draconiens qui voudraient s'élever jusqu'à sa garde. Seuls les plus forts du Vol noir peuvent entrer dans son repaire. Ils doivent porter une clé, une amulette accordée par le {red:general-drakkisath}général Drakkisath{/red} au {red:blackrock-spire}Pic Blackrock{/red}. Sans elle, ses protections barrent le chemin.

Certains, qui ne sont pas des dragons, ont trouvé d'autres chemins vers cette clé. La dragonne bleue {link:haleh}Haleh{/link}, de {link:winterspring}Berceau-de-l'Hiver{/link}, sait comment reconstituer une telle amulette, et {link:rexxar}Rexxar{/link} sait comment en gagner une par la ruse et par le sang. On dit que la mère de la couvée repose dans la salle la plus profonde de sa caverne. Ceux qui veulent l'affronter doivent descendre jusqu'à elle.]=],
		},
		{
			title = "Dans le repaire",
			text = [=[• {b}Le tunnel.{/b} Un long passage serpente depuis la tourbière. Des gardiens onyxiens, draconiens de sa garde, se tiennent tout du long et ne laissent passer aucun étranger.
• {b}Les nids.{/b} De profondes grottes s'ouvrent dans les parois de la grande salle, et leur sol est couvert d'œufs. Quand leur mère appelle, les dragonnets en jaillissent en essaims.
• {b}La grande salle.{/b} Une vaste salle de pierre noire au bout du tunnel, où attend {link:onyxia}Onyxia{/link}. Les crevasses de son sol s'ouvrent et crachent du feu. Quand elle prend son envol, toute la caverne brûle sous son souffle.]=],
		},
	},
})

Translate("frFR", "onyxia", {
	title = "Onyxia",
	subtitle = "Mère de la couvée du Vol noir",
	found = "La grande salle au bout du Repaire d'Onyxia",
	hint = [=[Descendez dans la caverne sous la Tourbière du Ver, où attend la mère de la couvée.]=],
	allegiance = "Vol noir",
	aliases = { "Dame Onyxia" },
	sections = {
