			title = "Résumé",
			text = [=[Onyxia est une fille d'{link:deathwing}Aile-de-mort{/link}, le Destructeur, et la jumelle de {red:nefarian}Nefarian{/red}, qui règne sur les hauteurs du {red:blackrock-spire}Pic Blackrock{/red}. Elle est la mère de la couvée du Vol noir. De son repaire sous la {link:wyrmbog}Tourbière du Ver{/link}, dans le {link:dustwallow-marsh}Marécage d'Âprefange{/link}, elle élève une nouvelle génération de la parenté de son père. Ses œufs couvrent les marécages du sud, et dragonnets, drakes et draconiens la servent. Elle est immense, rusée et fière. Son souffle est de feu, et elle regarde les mortels comme des proies. Ceux qui sont entrés sans y être invités dans son repaire, elle les a accueillis comme un repas qui lui épargnait la peine de chasser.]=],
		},
		{
			title = "Importance",
			text = [=[Nefarian tient le {link:blackrock-mountain}Mont Blackrock{/link} et ses orcs dans les {link:eastern-kingdoms}Royaumes de l'est{/link}. Onyxia tient le sud du {link:dustwallow-marsh}Marécage d'Âprefange{/link} en {link:kalimdor}Kalimdor{/link}, près de {link:theramore-isle}Theramore{/link} et des terres de la {link:horde}Horde{/link}. Sa couvée a chassé les ogres Cognepierres de leur foyer. Son propre vol l'honore : monter la garde auprès d'elle s'appelle une ascension. Pour les peuples des deux continents, elle est un danger dont nul n'a encore mesuré toute la portée.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Sa couvée fondit sur le village des ogres Cognepierres et les chassa vers le nord.
• Elle éparpilla ses œufs dans le cloaque aux dragons, pour emplir la {link:wyrmbog}Tourbière du Ver{/link} de ses petits.
• Elle protégea son repaire par des sortilèges, afin que nul n'y entre hormis les élus de son vol.
• Sa garde est choisie par les épreuves de {link:emberstrife}Brandeguerre{/link} et consacrée par le rite du général Drakkisath.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit quand Onyxia éclot, ni quand elle vint pour la première fois au {link:dustwallow-marsh}Marécage d'Âprefange{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La couvée d'Onyxia",
			hint = [=[Aidez l'érudit Cognepierres à découvrir qui a chassé son peuple de son foyer.]=],
			text = [=[Dans les cœurs et les langues de dragonnets calcinés, {link:draz-zilb}Draz'Zilb{/link} des Cognepierres lut le nom de celle qui les avait envoyés : Onyxia, fille du seigneur dragon noir. Il ne pouvait croire qu'elle était venue seulement pour brûler un village d'ogres. Il avertit son suzerain, et son suzerain ne voulut rien entendre. Draz'Zilb envoya donc d'autres que lui dans le cloaque aux dragons pour briser ses œufs avant que d'autres dragonnets ne puissent éclore. Pour un temps au moins, sa couvée ne grandirait plus.]=],
		},
		{
			title = "La grande mascarade",
			hint = [=[Soyez dans la salle du trône de Stormwind quand la mascarade prend fin.]=],
			text = [=[Pendant de longues années, Onyxia porta un visage humain à la cour de {link:stormwind-city}Stormwind{/link}. Sous les traits de {link:katrana-prestor}dame Katrana Prestor{/link}, elle se tenait aux côtés du régent, {link:bolvar-fordragon}Bolvar Fordragon{/link}, et par un médaillon façonné dans l'une de ses propres écailles, elle tenait son esprit captif. Puis le maréchal {red:reginald-windsor}Reginald Windsor{/red} s'échappa des prisons de {link:blackrock-mountain}Blackrock{/link} avec ses preuves, et il vint dans la salle du trône pour la nommer. Elle se moqua de lui, appela ses gardes et rejeta son déguisement. Windsor mourut là, mais le sortilège était rompu. Onyxia s'enfuit de la cité vers son repaire du marais. Elle laissa à Bolvar le médaillon brisé, et la certitude d'avoir été sa marionnette.]=],
		},
		{
			title = "Nouvelles portées par le vent",
			hint = [=[Écoutez ce que le vent a porté jusqu'au chef de guerre de la Horde.]=],
			text = [=[Des nouvelles parvinrent à {link:thrall}Thrall{/link}, à {link:orgrimmar}Orgrimmar{/link}, depuis les {link:eastern-kingdoms}Royaumes de l'est{/link}. La mère de la couvée du Vol noir avait été chassée d'un siège de pouvoir à {link:stormwind-city}Stormwind{/link}, et elle s'était enfuie vers son repaire du {link:dustwallow-marsh}Marécage d'Âprefange{/link}. Le chef de guerre ne souffrirait pas qu'elle demeure si près des cités de la {link:horde}Horde{/link}. Mieux valait frapper le premier, jugea-t-il, qu'attendre son coup. Il voulait qu'elle soit détruite.]=],
		},
		{
			title = "La clé du repaire",
			hint = "Obtenez une amulette que ses protections ne peuvent refuser.",
			text = [=[Seule une amulette accordée dans le rite de sang du général Drakkisath ouvre le repaire d'Onyxia. Ses ennemis trouvèrent deux chemins vers une telle clé. Pour {link:stormwind-city}Stormwind{/link}, la dragonne bleue {link:haleh}Haleh{/link} prit un fragment brisé, fait d'une écaille d'Onyxia elle-même, et le rendit entier avec le sang du général. Pour la {link:horde}Horde{/link}, {link:rexxar}Rexxar{/link} envoya un champion auprès de {link:myranda-the-hag}Myranda la Mégère{/link} pour obtenir une illusion. Sous l'apparence d'un jeune dragon noir, le champion passa les épreuves de {link:emberstrife}Brandeguerre{/link}. La comédie ne pouvait survivre au Pic, aussi le sang fut-il pris par l'épée. D'une façon ou d'une autre, l'Amulette de Feu-drake fut faite, et ses protections ne purent plus barrer la porte.]=],
		},
		{
			title = "La tête de la mère de la couvée",
			hint = [=[Affrontez la mère de la couvée dans les profondeurs de son repaire.]=],
			text = [=[Onyxia tomba dans son propre repaire, et sa tête fut emportée hors du marais. À {link:stormwind-city}Stormwind{/link}, le généralissime {link:bolvar-fordragon}Bolvar{/link} la salua comme une justice enfin rendue et comme l'honneur de son royaume restauré, et la tête du dragon fut suspendue aux arches de la cité, à la vue de tous. À {link:orgrimmar}Orgrimmar{/link}, même le calme de {link:thrall}Thrall{/link} se brisa un instant à sa vue.]=],
		},
	},
	mentions = {
		{ text = "La couvée d'Onyxia" },
		{ text = "La grande mascarade" },
		{ text = "L'Œil du dragon" },
