		{
			text = [=[La forge de Quel'Serrar, une lame chauffée dans son souffle et trempée dans son sang]=],
		},
		{ text = "Victoire pour la {link:horde}Horde{/link}" },
		{ text = "Victoire pour l'{link:alliance}Alliance{/link}" },
	},
	bonds = {
		{ id = "deathwing", name = "Aile-de-mort", note = "son père" },
