		{ id = "draz-zilb", name = "Draz'Zilb", note = "a appris son nom de ses dragonnets" },
		{ id = "rexxar", name = "Rexxar", note = "a montré à la Horde le chemin de son repaire" },
		{ id = "haleh", name = "Haleh", note = "a forgé une clé contre ses protections" },
	},
})
